<?php
namespace qqworld_collector\module\pseudo_original; use qqworld_collector\lib; class artificial_intelligence extends lib { var $log_id = 'artificial-intelligence'; public function init() { add_action( 'admin_enqueue_scripts', array($this, 'admin_enqueue_scripts') ); add_filter( 'qqworld-collector-script-translation-array', array($this, 'add_translation_array') ); add_action( 'add_meta_boxes', array($this, 'add_meta_boxes') ); add_action( 'wp_ajax_qqworld-collector-pseudo-original-artificial-intelligence', array($this, 'ajax_artificial_intelligence') ); add_action( 'wp_ajax_nopriv_qqworld-collector-pseudo-original-artificial-intelligence', array($this, 'ajax_artificial_intelligence') ); add_action( 'wp_insert_post', array($this, 'get_artificial_intelligence'), 10, 2 ); } public function admin_enqueue_scripts() { $screen = get_current_screen(); if ($screen->base == 'post') { wp_enqueue_style('animate'); wp_enqueue_script('noty'); wp_enqueue_style('noty'); wp_enqueue_script( 'qqworld-collector-pseudo-original-artificial-intelligence' ); } } public function add_translation_array($translation_array) { global $post; $screen = get_current_screen(); if ($screen->base == 'post') { $translation_array['pseudo_original_activated'] = apply_filters( 'qqworld-collector-activated-module-pseudo-original', false ); $translation_array['text']['please_check_at_least_one_item_that_requires_ai_processing'] = __('Please check at least one item that requires AI processing.', $this->text_domain); $translation_array['text']['please_fill_in_what_you_need_ai_to_do_for_you'] = __('Please fill in what you need AI to do for you.', $this->text_domain); } return $translation_array; } public function add_meta_boxes() { $id = 'artificial-intelligence'; $title = __( 'Artificial Intelligence', $this->text_domain ); $callback = array($this, 'artificial_intelligence'); $screen = get_post_types(array('public'=>true, 'show_ui' => true)); $context = 'side'; $priority = 'default'; $callback_args = null; add_meta_box($id, $title, $callback, $screen, $context, $priority, $callback_args ); } public function artificial_intelligence($post) { ?><div class="tagsdiv">
	<p><label for="artificial_intelligence_types"><strong><?php _e('API', $this->text_domain); ?></strong></label></p>
	<p><select class="selectstyle" id="artificial_intelligence_types" style="width: 100%;">
	<?php
 $apis = apply_filters( 'qqworld-collector-pseudo-original-get-ai-apis', array() ); foreach ($apis as $api => $label ) { print '<option value="'.$api.'" ' . selected($api, $this->options->qc_pseudo_original_artificial_intelligence_api, true) .'>'.$label.'</option>'; } ?>
	</select><br /><br /><span class="qc-icon info"><?php printf(__('Don\'t forget to <a href="%s" target="_blank">set the API Key</a> of the relevant interface before use. Note that you do not need to invoke artificial intelligence to process content when publishing posts.', $this->text_domain), admin_url('admin.php?page=pseudo-original-settings#artificial-intelligence') ); ?></span></p>
	<p><label for="artificial_intelligence_types"><strong><?php _e('Content', $this->text_domain); ?></strong></label></p>
	<ul>
		<li><label><input type="checkbox" value="post_title" id="artificial-intelligence-post-title" <?php checked(1, in_array('post_title', $this->options->qc_pseudo_original_artificial_intelligence_content)); ?> /> <?php _e('Post Title', $this->text_domain); ?></label></li>
		<li><label><input type="checkbox" value="post_content" id="artificial-intelligence-post-content" <?php checked(1, in_array('post_content', $this->options->qc_pseudo_original_artificial_intelligence_content)); ?>/> <?php _e('Post Content', $this->text_domain); ?></label></li>
		<li><label><input type="checkbox" value="post_excerpt" id="artificial-intelligence-post-excerpt" <?php checked(1, in_array('post_excerpt', $this->options->qc_pseudo_original_artificial_intelligence_content)); ?>/> <?php _e('Post Excerpt', $this->text_domain); ?></label></li>
	</ul>
	<p class="desciption"><?php _e('Select the content what you want the AI to process.', $this->text_domain); ?></p>
	<p><label for="artificial_intelligence_what_to_do"><strong><?php _e('What to do', $this->text_domain); ?></strong></label></p>
	<p>
		<textarea id="artificial_intelligence_what_to_do" class="large-text" rows="3" placeholder="<?php _e('For example: Please translate the following content into English.', $this->text_domain); ?>"><?php print $this->options->qc_pseudo_original_artificial_intelligence_what_to_do; ?></textarea><br /><?php _e('Please enter what you need AI to do for you.', $this->text_domain); ?>
	</p>
	<p class="ajaxtag hide-if-no-js">
		<button id="artificial_intelligence_submit" type="button" class="button button-primary button-large qc-icon ai"><?php _e('Start Processing', $this->text_domain); ?></button>
	</p>
	<p class="ajaxtag hide-if-no-js">
		<button id="artificial_intelligence_assistant" type="button" class="button button-large qc-icon ai2"><?php _e('AI Assistant', $this->text_domain); ?></button>
	</p>
</div><?php
 } public function ajax_artificial_intelligence() { extract($_POST); $results = array('data' => $content); $args = array( 'api' => $api, 'what_to_do' => $what_to_do ); foreach ($results['data'] as $key => &$value) { $value = apply_filters( 'qqworld-collector-artificial-intelligence', $value, $args ); } $results['success'] = 1; $results['msg'] = __('Processing complete.', $this->text_domain); print json_encode($results); exit; } public function get_artificial_intelligence($post_ID, $post = null) { global $wpdb; if ( !$this->options->qc_pseudo_original_artificial_intelligence_enabled || $post->post_status != 'publish' || !in_array($post->post_type, $this->options->qc_pseudo_original_artificial_intelligence_post_types) ) return; clean_post_cache($post); $post = get_post($post_ID); $arge = array(); $type = array(); foreach ($this->options->qc_pseudo_original_artificial_intelligence_content as $content) { $arge[$content] = apply_filters( 'qqworld-collector-artificial-intelligence', $post->$content ); $type[] = '%s'; } $result = $wpdb->update( $wpdb->posts, $arge, array( 'ID' => $post_ID ), $type, array( '%d' ) ); if ($this->options->qc_pseudo_original_artificial_intelligence_content_post_meta) { $content_post_meta = explode("\n", $this->options->qc_pseudo_original_artificial_intelligence_content_post_meta); $content_post_meta = array_map(array($this, 'deep_trim'), array_filter($content_post_meta)); $post_metas = get_post_meta($post_ID, '', true); foreach ($post_metas as $meta_key => $meta_values) { if (in_array($meta_key, $content_post_meta)) { $meta_value = apply_filters( 'qqworld-collector-artificial-intelligence', $meta_value ); update_post_meta($post_ID, $meta_key, $meta_value, $meta_values[0]); } } } } } ?>